<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:12px;color:#203c34;margin:40px}h1{color:#12694f}table{width:100%;border-collapse:collapse;margin:30px 0}td,th{padding:15px 8px;border-bottom:1px solid #dde6df;text-align:left}.right{text-align:right}.muted{color:#708078}</style></head><body><h2>MFARO SOFTWARE</h2><h1>Credit note</h1><p>{{ $note->number }} · Invoice {{ $invoice->number }}</p><table><tr><td><b>{{ $seller['name'] }}</b><p>{{ $seller['address'] ?? '' }}</p><p>VAT: {{ $seller['vat_number'] ?: 'Not configured' }}</p></td><td><b>{{ $customer['name'] }}</b><p>{{ $customer['billing_email'] }}</p></td></tr></table><p>Issued: {{ $note->issued_at }} UTC</p><p>Reason: {{ $note->reason }}</p><table><tr><th>Refund credit</th><th class="right">{{ $note->currency }}</th></tr><tr><td>Subtotal credited</td><td class="right">{{ $note->subtotal }}</td></tr><tr><td>Tax credited</td><td class="right">{{ $note->tax }}</td></tr><tr><td><b>Total credited</b></td><td class="right"><b>{{ $note->total }}</b></td></tr></table><p class="muted">This document records a refund against the original invoice. It does not create a new payment or change subscription access.</p></body></html>
